using JamunaBank.Procurement.API.DTOs;using JamunaBank.Procurement.API.Models;using JamunaBank.Procurement.API.Repositories.Interfaces;using JamunaBank.Procurement.API.Services.Interfaces;
namespace JamunaBank.Procurement.API.Services.Implementations;
public sealed class SupportingService(ISupportingRepository repository,ICurrentUserService currentUser):ISupportingService
{
 public Task<StoredProcedureResult?>AddAttachmentAsync(AddAttachmentMetadataRequest r,CancellationToken c){if(ValidType(r.EntityType) is not string||r.EntityId<=0||string.IsNullOrWhiteSpace(r.FileName)||string.IsNullOrWhiteSpace(r.OriginalFileName)||string.IsNullOrWhiteSpace(r.StorageKey)||r.FileSize<0)throw new ArgumentException("Valid attachment metadata is required.");return repository.AddAttachmentAsync(r,currentUser.EmployeeId,c);}public Task<IReadOnlyList<AttachmentMetadataDto>>GetAttachmentsAsync(string t,long id,CancellationToken c)=>repository.GetAttachmentsAsync(ValidType(t),Valid(id),c);public Task<StoredProcedureResult?>AddCommentAsync(AddCommentRequest r,CancellationToken c){Valid(r.RequisitionId);if(r.RequisitionItemId<=0)throw new ArgumentException("Requisition item ID must be positive.");if(string.IsNullOrWhiteSpace(r.CommentType)||string.IsNullOrWhiteSpace(r.CommentText))throw new ArgumentException("Comment type and text are required.");return repository.AddCommentAsync(r,currentUser.EmployeeId,c);}public Task<IReadOnlyList<CommentDto>>GetCommentsAsync(long id,CancellationToken c)=>repository.GetCommentsAsync(Valid(id),c);public Task<IReadOnlyList<ApprovalHistoryDto>>GetApprovalHistoryAsync(long id,CancellationToken c)=>repository.GetApprovalHistoryAsync(Valid(id),c);public Task<IReadOnlyList<WorkflowHistoryDto>>GetWorkflowHistoryAsync(long id,CancellationToken c)=>repository.GetWorkflowHistoryAsync(Valid(id),c);public Task<IReadOnlyList<SupportingProcurementStatusHistoryDto>>GetProcurementHistoryAsync(long id,CancellationToken c)=>repository.GetProcurementHistoryAsync(Valid(id),c);public Task<IReadOnlyList<AuditLogDto>>GetAuditAsync(string?n,long?id,int p,int s,CancellationToken c){if(id<=0||p<1||s is<1 or>200)throw new ArgumentException("Invalid audit filter or paging.");return repository.GetAuditAsync(string.IsNullOrWhiteSpace(n)?null:n.Trim(),id,p,s,c);}private static long Valid(long id){if(id<=0)throw new ArgumentOutOfRangeException(nameof(id));return id;}private static string ValidType(string t){var x=t?.Trim().ToUpperInvariant();if(x is not("REQUISITION"or"REQUISITION_ITEM"or"APPROVAL"or"PROCUREMENT_STATUS"or"WORK_ORDER"or"COMMENT"or"OTHER"))throw new ArgumentException("Unsupported attachment entity type.");return x;}
}
